    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Machining - Groove Milling$q$, 'process', 'single', false, true, true, $q$Milling a groove along its length, one pass, as the Filleting calculator times an edge (the workbook's End Milling sheet).$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET description = $q$Milling a groove along its length, one pass, as the Filleting calculator times an edge (the workbook's End Milling sheet).$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Edge Length$q$, $q$Edge Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Edges$q$, $q$Edges$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Cutter Diameter$q$, $q$Cutter Diameter (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Teeth$q$, $q$Teeth$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Speed Min$q$, $q$Speed Min (m/min)$q$, $q$number$q$, $q$m/min$q$, $q$machining_lookup$q$, $q$tblMillingConditions$q$, $q$SpeedMinMPerMin$q$, NULL, 5, true),
    (v_id, $q$Speed Max$q$, $q$Speed Max (m/min)$q$, $q$number$q$, $q$m/min$q$, $q$machining_lookup$q$, $q$tblMillingConditions$q$, $q$SpeedMaxMPerMin$q$, NULL, 6, true),
    (v_id, $q$Feed per Tooth Min$q$, $q$Feed per Tooth Min (mm/tooth)$q$, $q$number$q$, $q$mm/tooth$q$, $q$machining_lookup$q$, $q$tblMillingConditions$q$, $q$FeedPerToothMinMm$q$, NULL, 7, true),
    (v_id, $q$Feed per Tooth Max$q$, $q$Feed per Tooth Max (mm/tooth)$q$, $q$number$q$, $q$mm/tooth$q$, $q$machining_lookup$q$, $q$tblMillingConditions$q$, $q$FeedPerToothMaxMm$q$, NULL, 8, true),
    (v_id, $q$Range Position$q$, $q$Range Position$q$, $q$number$q$, NULL, NULL, NULL, NULL, $q$0.5$q$, 9, true),
    (v_id, $q$Max Spindle Speed$q$, $q$Max Spindle Speed (rpm)$q$, $q$number$q$, $q$rpm$q$, NULL, NULL, NULL, NULL, 10, true),
    (v_id, $q$Approach Length$q$, $q$Approach Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, $q$10$q$, 11, true),
    (v_id, $q$Cutting Speed$q$, $q$Cutting Speed (m/min)$q$, $q$calculated$q$, $q$m/min$q$, NULL, NULL, NULL, $q${Speed Min} + {Range Position} * ({Speed Max} - {Speed Min})$q$, 12, false),
    (v_id, $q$Feed per Tooth$q$, $q$Feed per Tooth (mm/tooth)$q$, $q$calculated$q$, $q$mm/tooth$q$, NULL, NULL, NULL, $q${Feed per Tooth Min} + {Range Position} * ({Feed per Tooth Max} - {Feed per Tooth Min})$q$, 13, false),
    (v_id, $q$Spindle Speed$q$, $q$Spindle Speed (rpm)$q$, $q$calculated$q$, $q$rpm$q$, NULL, NULL, NULL, $q$min({Max Spindle Speed}, {Cutting Speed} * 1000 / (pi * {Cutter Diameter}))$q$, 14, false),
    (v_id, $q$Machining Time$q$, $q$Machining Time (min)$q$, $q$calculated$q$, $q$min$q$, NULL, NULL, NULL, $q$({Edge Length} + {Approach Length} + {Cutter Diameter} / 2) / ({Feed per Tooth} * {Teeth} * {Spindle Speed})$q$, 15, false),
    (v_id, $q$Time per Edge$q$, $q$Time per Edge (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$ceil({Machining Time} * 60)$q$, 16, false),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Edges} * {Time per Edge}$q$, 17, false);

  INSERT INTO public.process_calculator_mappings
    (process_group, process_route, operation, calculator_id, calculator_name, is_active, display_order, machine_class, canonical_process_id)
  SELECT 'Machining', s.station, $q$Groove Milling$q$, v_id, $q$Machining - Groove Milling$q$, true, 743, s.cls,
         (SELECT pt.id FROM public.process_taxonomy pt WHERE pt.process_group = 'Machining' AND pt.process_name = s.station LIMIT 1)
  FROM (VALUES ($q$2_axis_lathe$q$, $q$2 Axis Lathe$q$), ($q$3_axis_lathe$q$, $q$3 Axis Lathe$q$), ($q$2_axis_bar_feed_lathe_with_sub_spindle$q$, $q$2 Axis Bar Feed Lathe with Sub Spindle$q$), ($q$3_axis_bar_feed_lathe_with_sub_spindle$q$, $q$3 Axis Bar Feed Lathe with Sub Spindle$q$), ($q$simultaneous_turning$q$, $q$Simultaneous Turning$q$), ($q$machining_millturn$q$, $q$MillTurn$q$), ($q$3_axis_mill$q$, $q$3 Axis Mill$q$), ($q$4_axis_mill$q$, $q$4 Axis Mill$q$), ($q$5_axis_mill$q$, $q$5 Axis Mill$q$)) AS s(cls, station)
  ON CONFLICT (process_group, process_route, operation) DO UPDATE
  SET calculator_id = EXCLUDED.calculator_id,
      calculator_name = EXCLUDED.calculator_name,
      machine_class = EXCLUDED.machine_class,
      is_active = true,
      canonical_process_id = EXCLUDED.canonical_process_id;
END
$calc$;

-- Machining - Countersinking
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Machining - Countersinking$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Machining - Countersinking$q$, 'process', 'single', false, true, true, $q$Countersinking each hole after it is drilled, timed as the Machining calculator workbook (memory/Machining - Calculator Database (1).xlsx) times a drill (its Drilling sheet): n = 1000 v / (pi D) at the countersink's diameter, capped at the machine's spindle limit; a 90 degree countersink cuts (countersink diameter - hole diameter) / 2 deep; time = (that depth + 10 mm) / (feed x n), rounded up to whole seconds a hole, at the workbook's drilling speed and feed for the material and diameter (tblDrillReamData). Was a flat 6 s a hole (user decision 2026-11-25).$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET description = $q$Countersinking each hole after it is drilled, timed as the Machining calculator workbook (memory/Machining - Calculator Database (1).xlsx) times a drill (its Drilling sheet): n = 1000 v / (pi D) at the countersink's diameter, capped at the machine's spindle limit; a 90 degree countersink cuts (countersink diameter - hole diameter) / 2 deep; time = (that depth + 10 mm) / (feed x n), rounded up to whole seconds a hole, at the workbook's drilling speed and feed for the material and diameter (tblDrillReamData). Was a flat 6 s a hole (user decision 2026-11-25).$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Countersink Diameter$q$, $q$Countersink Diameter (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Hole Diameter$q$, $q$Hole Diameter (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Holes$q$, $q$Holes$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Speed Min$q$, $q$Speed Min (m/min)$q$, $q$number$q$, $q$m/min$q$, $q$machining_lookup$q$, $q$tblDrillReamData$q$, $q$SpeedMinMPerMin$q$, NULL, 4, true),
    (v_id, $q$Speed Max$q$, $q$Speed Max (m/min)$q$, $q$number$q$, $q$m/min$q$, $q$machining_lookup$q$, $q$tblDrillReamData$q$, $q$SpeedMaxMPerMin$q$, NULL, 5, true),
    (v_id, $q$Feed$q$, $q$Feed (mm/rev)$q$, $q$number$q$, $q$mm/rev$q$, $q$machining_lookup$q$, $q$tblDrillReamData$q$, $q$FeedMmPerRev$q$, NULL, 6, true),
    (v_id, $q$Range Position$q$, $q$Range Position$q$, $q$number$q$, NULL, NULL, NULL, NULL, $q$0.5$q$, 7, true),
    (v_id, $q$Max Spindle Speed$q$, $q$Max Spindle Speed (rpm)$q$, $q$number$q$, $q$rpm$q$, NULL, NULL, NULL, NULL, 8, true),
    (v_id, $q$Approach Length$q$, $q$Approach Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, $q$10$q$, 9, true),
    (v_id, $q$Countersink Depth$q$, $q$Countersink Depth (mm)$q$, $q$calculated$q$, $q$mm$q$, NULL, NULL, NULL, $q$max(0, ({Countersink Diameter} - {Hole Diameter}) / 2)$q$, 10, false),
    (v_id, $q$Cutting Speed$q$, $q$Cutting Speed (m/min)$q$, $q$calculated$q$, $q$m/min$q$, NULL, NULL, NULL, $q${Speed Min} + {Range Position} * ({Speed Max} - {Speed Min})$q$, 11, false),
    (v_id, $q$Spindle Speed$q$, $q$Spindle Speed (rpm)$q$, $q$calculated$q$, $q$rpm$q$, NULL, NULL, NULL, $q$min({Max Spindle Speed}, {Cutting Speed} * 1000 / (pi * {Countersink Diameter}))$q$, 12, false),
    (v_id, $q$Machining Time$q$, $q$Machining Time (min)$q$, $q$calculated$q$, $q$min$q$, NULL, NULL, NULL, $q$({Countersink Depth} + {Approach Length}) / ({Feed} * {Spindle Speed})$q$, 13, false),
    (v_id, $q$Time per Hole$q$, $q$Time per Hole (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$ceil({Machining Time} * 60)$q$, 14, false),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Holes} * {Time per Hole}$q$, 15, false);

  INSERT INTO public.process_calculator_mappings
    (process_group, process_route, operation, calculator_id, calculator_name, is_active, display_order, machine_class, canonical_process_id)
  SELECT 'Machining', s.station, $q$Countersinking$q$, v_id, $q$Machining - Countersinking$q$, true, 751, s.cls,
         (SELECT pt.id FROM public.process_taxonomy pt WHERE pt.process_group = 'Machining' AND pt.process_name = s.station LIMIT 1)
  FROM (VALUES ($q$2_axis_lathe$q$, $q$2 Axis Lathe$q$), ($q$3_axis_lathe$q$, $q$3 Axis Lathe$q$), ($q$2_axis_bar_feed_lathe_with_sub_spindle$q$, $q$2 Axis Bar Feed Lathe with Sub Spindle$q$), ($q$3_axis_bar_feed_lathe_with_sub_spindle$q$, $q$3 Axis Bar Feed Lathe with Sub Spindle$q$), ($q$simultaneous_turning$q$, $q$Simultaneous Turning$q$), ($q$machining_millturn$q$, $q$MillTurn$q$), ($q$3_axis_mill$q$, $q$3 Axis Mill$q$), ($q$4_axis_mill$q$, $q$4 Axis Mill$q$), ($q$5_axis_mill$q$, $q$5 Axis Mill$q$)) AS s(cls, station)
  ON CONFLICT (process_group, process_route, operation) DO UPDATE
  SET calculator_id = EXCLUDED.calculator_id,
      calculator_name = EXCLUDED.calculator_name,
      machine_class = EXCLUDED.machine_class,
      is_active = true,
      canonical_process_id = EXCLUDED.canonical_process_id;
END
$calc$;

DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Machining - Center Drilling$q$, 14, 9),
    ($q$Machining - Chamfering$q$, 17, 9),
    ($q$Machining - Filleting$q$, 17, 9),
    ($q$Machining - Groove Milling$q$, 17, 9),
    ($q$Machining - Countersinking$q$, 15, 9)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.is_active) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1152: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
